import { createHash, randomBytes, timingSafeEqual } from "node:crypto";
export const AUTOMATION_WEBHOOK_PLATFORM = "automation-webhook";
export const AUTOMATION_WEBHOOK_MAX_BODY_BYTES = 64 * 1024;
const WEBHOOK_TOKEN_RE = /^[A-Za-z0-9_-]{43}$/;
export function createAutomationWebhookToken() {
    return randomBytes(32).toString("base64url");
}
export function isAutomationWebhookToken(value) {
    return WEBHOOK_TOKEN_RE.test(value);
}
export function automationWebhookPath(token) {
    return `/_agent-native/automations/webhook/${token}`;
}
export function automationWebhookTokenHash(token) {
    return createHash("sha256").update(token, "utf8").digest("hex");
}
export function webhookTokensMatch(expected, received) {
    if (!expected || !isAutomationWebhookToken(received))
        return false;
    const expectedBuffer = Buffer.from(expected);
    const receivedBuffer = Buffer.from(received);
    return (expectedBuffer.length === receivedBuffer.length &&
        timingSafeEqual(expectedBuffer, receivedBuffer));
}
